"""
    Given a key and a list, find possible matches
    Right now it just checks for case
    """
def find_possible(key: Any, possible: Any) -> object {
    if (key in possible) {
        return key;
    }
    possible = [
        x
        for x in possible
        if (x.lower() == key)
    ];
    if (possible == []) {
        return None;
    }
    return possible[0];
}

